-- INVEZ Database Schema
-- Import via phpMyAdmin: Create database "invez" first, then import this file.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- -------------------------------------------------------
-- Tables
-- -------------------------------------------------------

CREATE TABLE IF NOT EXISTS `members` (
  `id`            INT AUTO_INCREMENT PRIMARY KEY,
  `first_name`    VARCHAR(100) NOT NULL,
  `last_name`     VARCHAR(100) NOT NULL,
  `phone`         VARCHAR(20)  DEFAULT NULL,
  `email`         VARCHAR(255) UNIQUE NOT NULL,
  `username`      VARCHAR(50)  UNIQUE NOT NULL,
  `password_hash` VARCHAR(255) NOT NULL,
  `status`        VARCHAR(20)  NOT NULL DEFAULT 'pending',
  `created_at`    TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `admins` (
  `id`         INT AUTO_INCREMENT PRIMARY KEY,
  `username`   VARCHAR(50)  UNIQUE NOT NULL,
  `password`   VARCHAR(255) NOT NULL,
  `name`       VARCHAR(100) NOT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `properties` (
  `id`             INT AUTO_INCREMENT PRIMARY KEY,
  `category`       VARCHAR(50)  NOT NULL,
  `title`          VARCHAR(255) NOT NULL,
  `subtitle`       VARCHAR(255) DEFAULT NULL,
  `price`          BIGINT       DEFAULT NULL,
  `price_display`  VARCHAR(100) DEFAULT NULL,
  `location`       TEXT         DEFAULT NULL,
  `location_short` VARCHAR(100) DEFAULT NULL,
  `land_area`      VARCHAR(50)  DEFAULT NULL,
  `usable_area`    VARCHAR(50)  DEFAULT NULL,
  `floors`         VARCHAR(50)  DEFAULT NULL,
  `beds`           INT          DEFAULT NULL,
  `bathrooms`      INT          DEFAULT NULL,
  `parking`        VARCHAR(50)  DEFAULT NULL,
  `offices`        INT          DEFAULT NULL,
  `status`         VARCHAR(100) DEFAULT NULL,
  `description`    TEXT         DEFAULT NULL,
  `sort_order`     INT          DEFAULT 0,
  `is_active`      TINYINT(1)   DEFAULT 1,
  `token`          VARCHAR(32)  UNIQUE DEFAULT NULL,
  `created_at`     TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  `updated_at`     TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `property_highlights` (
  `id`          INT AUTO_INCREMENT PRIMARY KEY,
  `property_id` INT  NOT NULL,
  `content`     TEXT NOT NULL,
  `sort_order`  INT  DEFAULT 0,
  FOREIGN KEY (`property_id`) REFERENCES `properties`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `property_images` (
  `id`          INT AUTO_INCREMENT PRIMARY KEY,
  `property_id` INT          NOT NULL,
  `filename`    VARCHAR(255) NOT NULL,
  `sort_order`  INT          DEFAULT 0,
  FOREIGN KEY (`property_id`) REFERENCES `properties`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `property_interests` (
  `id`             INT AUTO_INCREMENT PRIMARY KEY,
  `transaction_id` CHAR(36)         UNIQUE DEFAULT NULL,
  `member_id`      INT              NOT NULL,
  `property_id`    INT              NOT NULL,
  `amount_percent` TINYINT UNSIGNED NOT NULL,
  `amount_value`   BIGINT           NOT NULL,
  `bank`           VARCHAR(10)      NOT NULL,
  `status`         VARCHAR(20)      NOT NULL DEFAULT 'pending',
  `slip_filename`  VARCHAR(255)     DEFAULT NULL,
  `created_at`     TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `articles` (
  `id`         INT AUTO_INCREMENT PRIMARY KEY,
  `icon`       VARCHAR(50)  DEFAULT 'file-text',
  `category`   VARCHAR(100) NOT NULL,
  `title`      VARCHAR(255) NOT NULL,
  `excerpt`    TEXT         DEFAULT NULL,
  `intro`      TEXT         DEFAULT NULL,
  `points`     JSON         DEFAULT NULL,
  `is_active`  TINYINT(1)   DEFAULT 1,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

