INSERT INTO `articles` (`id`,`icon`,`category`,`title`,`excerpt`,`intro`,`points`) VALUES
(1,'key','โรงแรม','3 สิ่งที่ต้องทำการบ้านหนักๆ ก่อนตัดสินใจซื้อ "โรงแรม"','การซื้อโรงแรมที่ดำเนินกิจการอยู่แล้วมาทำต่อ ข้อดีคือไม่ต้องเริ่มนับหนึ่งใหม่ แต่ต้องเช็กฐานลูกค้าเดิม ใบอนุญาต และสภาพระบบหลังบ้านก่อนควักกระเป๋า','การซื้อโรงแรมที่ดำเนินกิจการอยู่แล้วมาทำต่อ ข้อดีคือเราไม่ต้องเริ่มนับหนึ่งใหม่ แต่เพื่อให้การลงทุนราบรื่น มี 3 เรื่องสำคัญที่ต้องเช็กให้ชัวร์ก่อนควักกระเป๋า','[{"label":"ฐานลูกค้าเดิมและรีวิว","detail":"ลองเข้าไปดูรีวิวใน Agoda หรือ Google Maps ดูว่าลูกค้าเดิมบ่นหรือชมเรื่องอะไร เพราะนั่นคือสิ่งที่เราต้องเข้ามาปรับปรุงหรือรักษาไว้"},{"label":"ใบอนุญาตประกอบธุรกิจโรงแรม","detail":"อันนี้สำคัญมาก ต้องเช็กให้ละเอียดว่ามีครบถ้วนและยังไม่หมดอายุไหม"},{"label":"สภาพระบบหลังบ้าน","detail":"พวกงานระบบน้ำ ไฟ แอร์ และโครงสร้าง ถ้าต้องรีโนเวตใหญ่ อาจจะมีค่าใช้จ่ายที่บานปลายได้เลย"}]'),
(2,'activity','โรงพยาบาล / คลินิก','เปิดคลินิกหรือซื้อโรงพยาบาลต่อ ทำเลแบบไหนที่ตอบโจทย์?','ธุรกิจสุขภาพมาแรงมากในช่วงนี้ แต่การเลือกซื้อหรือเช่าตึกเพื่อทำโรงพยาบาลหรือคลินิก ต้องดูการเดินทาง โครงสร้างระบบเฉพาะทาง และกลุ่มเป้าหมายในพื้นที่ประกอบด้วย','ธุรกิจสุขภาพเป็นอะไรที่มาแรงมากในช่วงนี้ แต่การจะเลือกซื้อหรือเช่าตึกเพื่อทำโรงพยาบาลหรือคลินิก ไม่ใช่แค่ตึกสวยแล้วจะจบ แต่ต้องดูสิ่งเหล่านี้ประกอบด้วย','[{"label":"การเดินทางและที่จอดรถ","detail":"ลูกค้าที่มารับบริการด้านสุขภาพต้องการความสะดวกสบาย ถ้าที่จอดรถน้อยหรือเข้าถึงยาก ลูกค้าอาจจะเปลี่ยนใจได้ง่ายๆ"},{"label":"โครงสร้างที่รองรับงานระบบ","detail":"ตึกที่จะทำสถานพยาบาลต้องมีพื้นที่สำหรับวางระบบเฉพาะทาง เช่น ห้องเอกซเรย์ หรือระบบกำจัดขยะติดเชื้อ"},{"label":"กลุ่มเป้าหมายในพื้นที่","detail":"คลินิกความงาม คลินิกทำฟัน หรือโรงพยาบาลเฉพาะทาง ต่างก็มีกลุ่มลูกค้าที่ไม่เหมือนกัน การสำรวจคนในพื้นที่ก่อนจึงสำคัญมาก"}]'),
(3,'book-open','โรงเรียน / มหาวิทยาลัย','เปลี่ยนอสังหาฯ ให้เป็น "สถานศึกษา" มีอะไรที่ต้องคิดมากกว่าแค่ขนาดพื้นที่?','การลงทุนในอสังหาฯ ประเภทสถานศึกษา สิ่งสำคัญไม่ใช่แค่พื้นที่กว้างขวาง แต่คือความปลอดภัย การจราจรช่วงเร่งด่วน และพื้นที่สีเขียวสำหรับกิจกรรมเด็ก','การลงทุนในอสังหาริมทรัพย์ประเภทสถานศึกษา ไม่ว่าจะเป็นโรงเรียนนานาชาติ ติวเตอร์ หรือเนอร์สเซอรี่ สิ่งสำคัญไม่ใช่แค่พื้นที่กว้างขวาง แต่คือ "ความปลอดภัยและสภาพแวดล้อม"','[{"label":"ความปลอดภัยเป็นอันดับหนึ่ง","detail":"บันได ทางหนีไฟ มุมอับต่างๆ ต้องถูกออกแบบมาอย่างดีเพื่อให้ผ่านมาตรฐานของกระทรวงศึกษาธิการ"},{"label":"การจราจรช่วงเร่งด่วน","detail":"โรงเรียนมักจะเจอปัญหารถติดตอนเช้าและเย็น พื้นที่รอบๆ ต้องมีจุดจอดรับ-ส่งนักเรียนที่ไม่กระทบกับชุมชนเกินไป"},{"label":"พื้นที่สีเขียวและกิจกรรม","detail":"เด็กๆ ต้องการพื้นที่วิ่งเล่นและทำกิจกรรม การมีพื้นที่เปิดโล่งจะช่วยเพิ่มมูลค่าและความน่าสนใจให้สถานศึกษาได้เป็นอย่างดี"}]'),
(4,'layers','คอนโด','ช้อนซื้อ "คอนโดมือสอง" มาปล่อยเช่าหรือรีเซลยังไงให้คุ้มค่า?','ตลาดคอนโดมือสองยังคงเป็นที่นิยมของนักลงทุน เพราะมักได้ทำเลในเมืองที่หาไม่ได้แล้วในโครงการใหม่ๆ ต้องสังเกตนิติบุคคล ประวัติผู้เช่า และคำนวณส่วนต่างให้คุ้ม','ตลาดคอนโดมือสองยังคงเป็นที่นิยมของนักลงทุน เพราะมักจะได้ทำเลในเมืองที่หาไม่ได้แล้วในโครงการใหม่ๆ เทคนิคการเลือกซื้อง่ายๆ มีดังนี้','[{"label":"นิติบุคคลต้องแข็งแรง","detail":"ลองสังเกตสภาพส่วนกลาง สระว่ายน้ำ ลิฟต์ ถ้าได้รับการดูแลดี แสดงว่านิติฯ ทำงานเก่ง ซึ่งจะช่วยรักษาใจผู้เช่าและรักษามูลค่าตึกในระยะยาว"},{"label":"เช็กประวัติคนเช่าในตึก","detail":"ลองสืบดูว่าคนแถวนั้นเป็นใคร (คนทำงาน นักศึกษา หรือต่างชาติ) เพื่อเราจะได้แต่งห้องให้ตรงสเปกกลุ่มเป้าหมาย"},{"label":"ราคาต้องมีส่วนต่างให้ทำกำไร","detail":"คำนวณค่ารีโนเวตเผื่อไว้ด้วย เพื่อให้ตอนปล่อยเช่าหรือขายต่อยังได้ Yield ที่คุ้มเหนื่อย"}]'),
(5,'home','อพาร์ทเมนท์','ซื้ออพาร์ทเมนท์กินส่วนต่างรายเดือน เสือนอนกินจริงหรือเปล่า?','หลายคนฝันอยากมีอพาร์ทเมนท์เก็บค่าเช่าทุกเดือน แต่ต้องคำนวณค่าใช้จ่ายแฝง คัดกรองผู้เช่าอย่างรอบคอบ และใช้เทคโนโลยีช่วยทุ่นแรงในการบริหาร','หลายคนฝันอยากเป็นเสือนอนกิน มีอพาร์ทเมนท์เก็บค่าเช่าทุกเดือน แต่ในความเป็นจริง การบริหารอพาร์ทเมนท์ก็คืองานบริการอย่างหนึ่ง','[{"label":"ค่าใช้จ่ายแฝง","detail":"นอกจากรายรับแล้ว ต้องคำนวณค่าแม่บ้าน รปภ. ค่าน้ำไฟส่วนกลาง และงบซ่อมแซมห้องพักที่คนเก่าย้ายออกด้วย"},{"label":"การคัดกรองผู้เช่า","detail":"การมีผู้เช่าที่ดีจะช่วยลดปัญหาวุ่นวายไปได้เกินครึ่ง การตั้งกฎระเบียบที่ชัดเจนจึงเป็นเรื่องจำเป็น"},{"label":"เทคโนโลยีช่วยทุ่นแรง","detail":"ปัจจุบันมีระบบคีย์การ์ด ระบบจ่ายเงินออนไลน์ ช่วยให้เราไม่ต้องเฝ้าตึกเองตลอดเวลา ทำให้การเป็นเสือนอนกินใกล้ความจริงมากยิ่งขึ้นไปอีก"}]'),
(6,'tool','โรงงานอุตสาหกรรม','จะซื้อหรือเช่า "โรงงาน" ต้องดูใบอนุญาตอะไรบ้าง?','การหาโรงงานสักแห่ง สิ่งที่ต้องดูเป็นอันดับแรกไม่ใช่ขนาดตึก แต่คือสีผังเมือง ใบอนุญาต รง.4 และความพร้อมของระบบกำลังไฟฟ้าที่รองรับเครื่องจักร','การหาโรงงานอุตสาหกรรมสักแห่ง สิ่งที่ต้องดูเป็นอันดับแรกไม่ใช่ขนาดตึก แต่คือ "สีผังเมือง" และ "ใบอนุญาต"','[{"label":"ผังสีของที่ดิน","detail":"ต้องเช็กว่าที่ดินตรงนั้นเป็นสีอะไร (เช่น สีม่วงสำหรับอุตสาหกรรม) และสามารถตั้งโรงงานประเภทที่เราจะทำได้หรือไม่"},{"label":"ใบอนุญาต รง.4","detail":"สำหรับโรงงานบางประเภท จำเป็นต้องมีใบอนุญาตประกอบกิจการโรงงาน (รง.4) การซื้อโรงงานที่มีใบนี้อยู่แล้วจะช่วยประหยัดเวลาไปได้เยอะ"},{"label":"ความพร้อมของกำลังไฟ","detail":"โรงงานต้องใช้ไฟเยอะกว่าปกติ ต้องเช็กว่าระบบไฟฟ้าในตึกและหม้อแปลงรองรับเครื่องจักรของเราได้มากน้อยแค่ไหน"}]'),
(7,'package','คลังสินค้า / โกดัง','โกดังที่ดีไม่ใช่แค่กว้าง แต่ต้อง "ขนส่งสะดวก" ด้วย','ในยุค E-commerce โตไม่หยุด คลังสินค้าและโกดังกลายเป็นที่ต้องการอย่างมาก โกดังที่ดีต้องมีความสูง วงเลี้ยวรถบรรทุก และทำเลที่เชื่อมต่อจุดกระจายสินค้าได้ดี','ในยุคที่ E-commerce โตไม่หยุด คลังสินค้าและโกดังกลายเป็นที่ต้องการเป็นอย่างมาก แต่โกดังที่คนอยากเช่าหรือซื้อ ต้องมีองค์ประกอบเหล่านี้','[{"label":"ความสูงและน้ำหนักที่รับได้","detail":"หลังคาต้องสูงพอที่จะซ้อนพาเลทได้เยอะๆ และพื้นต้องรับน้ำหนักได้ตามมาตรฐานของสินค้าที่จะมาลง"},{"label":"ระยะวงเลี้ยวของรถบรรทุก","detail":"ประตูทางเข้าและพื้นที่หน้าโกดังต้องกว้างพอให้รถเทรลเลอร์ หรือรถสิบล้อเลี้ยวเข้ามาโหลดของได้สะดวก"},{"label":"ทำเลที่เชื่อมต่อจุดกระจายสินค้า","detail":"ยิ่งใกล้ทางด่วน ท่าเรือ หรือจุดตัดการเดินทาง ยิ่งเป็นแต้มต่อที่ทำให้โกดังนั้นถูกจับจองได้เร็วขึ้น"}]'),
(8,'map','ที่ดิน','ซื้อที่ดินเปล่าเก็บไว้... ดูยังไงว่าแปลงไหนมีอนาคต?','การลงทุนในที่ดินเป็นการลงทุนที่คลาสสิกและมั่นคง แต่ต้องเช็กแนวเวนคืน ติดตามโครงสร้างพื้นฐานในอนาคต และเลือกที่ดินที่มีรูปทรงพร้อมใช้งาน','การลงทุนในที่ดินเป็นการลงทุนที่คลาสสิกและมั่นคง แต่เพื่อให้เงินไม่จมและงอกเงยในอนาคต ลองใช้หลักเกณฑ์นี้ในการเลือกดู','[{"label":"เช็กแนวเวนคืนและข้อจำกัดทางกฎหมาย","detail":"ก่อนซื้อต้องเช็กกับกรมโยธาฯ หรือหน่วยงานที่เกี่ยวข้องให้ชัวร์ว่า ที่ดินแปลงนี้ไม่มีโครงการเวนคืนตัดผ่าน หรืออยู่ในเขตแนวท่อแก๊สที่สร้างตึกไม่ได้"},{"label":"โครงสร้างพื้นฐานในอนาคต","detail":"ลองตามข่าวการตัดถนนใหม่ รถไฟฟ้า หรือการขยายตัวของชุมชน ที่ดินที่อยู่ใกล้จุดเหล่านี้มูลค่าจะโตแบบก้าวกระโดด"},{"label":"รูปทรงของที่ดิน","detail":"ที่ดินรูปสี่เหลี่ยมผืนผ้าหรือจัตุรัสจะจัดสรรและใช้ประโยชน์ได้ง่ายกว่าที่ดินรูปทรงแปลกๆ หรือเป็นเส้นก๋วยเตี๋ยว"}]'),
(9,'briefcase','สำนักงาน / ออฟฟิศ','เลือกออฟฟิศให้บริษัท ยุคนี้เขาดูกันที่อะไรบ้าง?','พฤติกรรมการทำงานเปลี่ยนไปมาก ออฟฟิศยุคใหม่ต้องอยู่ใกล้รถไฟฟ้า มีพื้นที่ยืดหยุ่นแบบ Co-working และระบบอินเทอร์เน็ตที่เสถียรเพื่อดึงดูดคนเก่ง','พฤติกรรมการทำงานของคนยุคนี้เปลี่ยนไปเป็นอย่างมาก การเลือกซื้อหรือเช่าพื้นที่สำนักงานในปัจจุบันจึงไม่ได้มองแค่ความกว้างอีกต่อไป','[{"label":"ใกล้รถไฟฟ้าคือหัวใจ","detail":"เพื่อดึงดูดคนเก่งๆ มาร่วมงาน ออฟฟิศที่เดินทางสะดวกด้วยขนส่งสาธารณะจะได้เปรียบมาก"},{"label":"พื้นที่ยืดหยุ่น","detail":"ยุคนี้คนชอบสไตล์ Co-working space พื้นที่ออฟฟิศที่สามารถปรับเปลี่ยนกั้นห้อง หรือทำมุมพักผ่อนได้ง่ายจะตอบโจทย์คนรุ่นใหม่"},{"label":"ความเสถียรของอินเทอร์เน็ตและงานระบบ","detail":"ระบบสายเคเบิลใยแก้วนำแสง และระบบแอร์ที่เปิด-ปิดได้ตามโซนที่ใช้งานจริง จะช่วยประหยัดงบให้บริษัทได้อีกมาก"}]'),
(10,'star','คฤหาสน์ / บ้านหรู','"บ้านหรู" ไม่ใช่แค่ใหญ่... แต่คือรสนิยมและความเป็นส่วนตัว','การเลือกซื้อคฤหาสน์หรือบ้านระดับ Luxury คนระดับนี้ไม่ได้มองหาแค่ที่ซุกหัวนอน แต่มองหาสังคม ความเป็นส่วนตัว ฟังก์ชันเฉพาะตัว และนิติบุคคลระดับพรีเมียม','การเลือกซื้อคฤหาสน์หรือบ้านระดับ Luxury ไม่เหมือนกับการซื้อบ้านทั่วไป เพราะคนระดับนี้ไม่ได้มองหาแค่ที่ซุกหัวนอน แต่มองหา "สังคมและคุณภาพชีวิต"','[{"label":"ความเป็นส่วนตัว (Privacy)","detail":"ระบบรักษาความปลอดภัยต้องแน่นหนา และทำเลต้องไม่พลุกพล่าน"},{"label":"ฟังก์ชันเฉพาะตัว","detail":"ต้องมีพื้นที่รองรับไลฟ์สไตล์ เช่น ห้องเก็บไวน์ Garage ติดแอร์สำหรับรถหรู หรือสระว่ายน้ำระบบเกลือ"},{"label":"นิติบุคคลระดับพรีเมียม","detail":"การดูแลส่วนกลางต้องเนี้ยบตลอดเวลา เพื่อรักษามูลค่าของหมู่บ้านให้คงความหรูหราไปนานๆ"}]'),
(11,'sun','สวนเกษตรกรรม','ซื้อ "ที่ดินทำเกษตร" ยุคนี้ ต้องดูอะไรให้งอกเงย?','เทรนด์การเป็นเจ้าของสวนผลไม้หรือฟาร์มเกษตรอินทรีย์กำลังมาแรง แต่ก่อนตัดสินใจต้องเช็ก 3 เรื่องหลัก คือแหล่งน้ำ สภาพดิน และเส้นทางการขนส่งผลผลิต','เทรนด์การเป็นเจ้าของสวนผลไม้หรือฟาร์มเกษตรอินทรีย์กำลังมาแรง แต่ก่อนจะตัดสินใจซื้อที่ดินสักผืนมาทำสวน ต้องเช็ก 3 เรื่องนี้ก่อน','[{"label":"แหล่งน้ำ","detail":"เป็นหัวใจสำคัญที่สุด ต้องดูว่ามีน้ำใช้ตลอดปีไหม หรือต้องขุดสระเพิ่ม"},{"label":"สภาพดินและสภาพอากาศ","detail":"ดินแถบนั้นเหมาะกับพืชที่เราจะปลูกหรือเปล่า"},{"label":"การขนส่ง","detail":"ผลผลิตทางการเกษตรเน่าเสียง่าย ทางเข้า-ออกต้องดี รถกระบะหรือรถบรรทุกต้องเข้าถึงสวนได้สะดวกเพื่อขนของไปขาย"}]'),
(12,'feather','ฟาร์มปศุสัตว์','อยากทำ "ฟาร์มปศุสัตว์" เริ่มต้นดูอสังหาฯ อย่างไรไม่ให้มีปัญหา?','ไม่ว่าจะเป็นฟาร์มวัว ฟาร์มหมู หรือฟาร์มไก่ สิ่งสำคัญคือการอยู่ร่วมกับชุมชน ระยะห่าง ระบบจัดการของเสีย และอากาศถ่ายเทเป็นเรื่องที่ต้องใส่ใจ','ไม่ว่าจะเป็นฟาร์มวัว ฟาร์มหมู หรือฟาร์มไก่ สิ่งสำคัญที่สุดไม่ใช่แค่ขนาดพื้นที่กว้างๆ แต่เป็นเรื่องของ "การอยู่ร่วมกับชุมชน"','[{"label":"ระยะห่างจากชุมชน","detail":"ต้องเช็กกฎหมายท้องถิ่นว่าต้องอยู่ห่างจากบ้านคนและแหล่งน้ำสาธารณะเท่าไหร่ เพื่อไม่ให้เรื่องกลิ่นหรือเสียงไปรบกวนคนอื่น"},{"label":"ระบบจัดการของเสีย","detail":"พื้นที่ต้องเอื้อต่อการทำระบบบำบัดน้ำเสียหรือทำไบโอแก๊ส"},{"label":"อากาศถ่ายเท","detail":"ทำเลควรมีลมพัดผ่านดี ไม่ร้อนอบอ้าว เพื่อสุขภาพที่ดีของสัตว์ในฟาร์ม"}]'),
(13,'flag','สนามกอล์ฟ','ลงทุนใน "สนามกอล์ฟ" อสังหาฯ ขนาดใหญ่ที่ต้องใส่ใจเรื่อง Landscape','สนามกอล์ฟเป็นอสังหาฯ ที่ใช้พื้นที่เยอะและมีมูลค่าสูง การซื้อหรือพัฒนาต่อต้องมองที่ Course Design คลับเฮ้าส์มาตรฐาน และงบประมาณดูแลรักษาระยะยาว','สนามกอล์ฟเป็นอสังหาฯ ที่ใช้พื้นที่เยอะและมีมูลค่าสูงมาก การจะซื้อหรือพัฒนาต่อ สิ่งที่นักลงทุนต้องมองคือ','[{"label":"การออกแบบสนาม (Course Design)","detail":"สนามมีความท้าทายดึงดูดให้นักกอล์ฟอยากมาซ้ำไหม"},{"label":"คลับเฮาส์และสิ่งอำนวยความสะดวก","detail":"นอกจากตีกอล์ฟแล้ว ร้านอาหาร ล็อกเกอร์ และที่พัก ต้องได้มาตรฐานระดับโรงแรม"},{"label":"งบประมาณการดูแลรักษา","detail":"คอร์สการดูแลหญ้าและระบบน้ำใหญ่มาก ต้องคำนวณต้นทุนตรงนี้ให้ดี"}]'),
(14,'truck','โชว์รูมรถยนต์','หาทำเล "โชว์รูมรถยนต์" ยุคนี้ ทำเลแบบไหนที่ลูกค้าอยากเลี้ยวเข้า?','โชว์รูมรถยนต์ต้องการพื้นที่โดดเด่นและเข้าถึงง่าย ต้องมีหน้ากว้างติดถนนใหญ่ ที่จอดรถเพียงพอ และโครงสร้างที่รองรับศูนย์บริการในอนาคตได้','โชว์รูมรถยนต์ต้องการพื้นที่ที่โดดเด่นและเข้าถึงง่ายมากๆ','[{"label":"หน้ากว้างและติดถนนใหญ่","detail":"ยิ่งหน้ากว้าง ยิ่งโชว์รถได้เยอะ และต้องอยู่ในจุดที่รถชะลอตัว ไม่ใช่ทางลงสะพานที่ขับผ่านไปเร็วๆ"},{"label":"พื้นที่จอดรถของลูกค้า","detail":"ถ้าลูกค้ามาแล้วไม่มีที่จอด โอกาสปิดการขายจะลดลงทันที"},{"label":"โครงสร้างรองรับศูนย์บริการ","detail":"นอกจากส่วนโชว์รูมด้านหน้าแล้ว ด้านหลังต้องมีพื้นที่และโครงสร้างที่รองรับการทำอู่ซ่อมและสต็อกอะไหล่ด้วย"}]'),
(15,'battery-charging','ปั๊มน้ำมัน / EV Station','ปั๊มน้ำมันยุคใหม่... เมื่อหัวใจเปลี่ยนเป็น "Community Mall" และ "EV Station"','ตอนนี้ปั๊มน้ำมันไม่ได้มีไว้แค่เติมน้ำมันเพียงอย่างเดียว แต่กลายเป็นจุดแวะพักผ่อนของคนเดินทาง ต้องคิดเรื่อง Traffic ร้านค้า และความพร้อมของระบบไฟ','ตอนนี้ปั๊มน้ำมันไม่ได้มีไว้แค่เติมน้ำมันเพียงอย่างเดียว แต่กลายเป็นจุดแวะพักผ่อนของคนเดินทาง','[{"label":"Traffic คือทุกสิ่ง","detail":"ต้องอยู่ฝั่งขาออกเมือง หรือจุดแวะพักที่คนมักจะจอดพักรถ"},{"label":"พื้นที่สำหรับร้านค้า","detail":"ยิ่งมีพื้นที่ให้ร้านกาแฟ ร้านสะดวกซื้อ หรือร้านอาหารมาเช่าเยอะ ยิ่งคืนทุนไว"},{"label":"ความพร้อมของระบบไฟ","detail":"หากจะทำสถานีชาร์จ EV (Fast Charge) ต้องเช็กกับทางการไฟฟ้าว่าในพื้นที่นั้นสามารถดึงไฟแรงสูงมาใช้ได้เพียงพอหรือไม่"}]'),
(16,'zap','โรงไฟฟ้า','ซื้อ-ขาย "โรงไฟฟ้า" ดีลใหญ่ที่ต้องดูเรื่องสัญญาและสิ่งแวดล้อม','การลงทุนในโรงไฟฟ้า ไม่ว่าจะเป็นโซลาร์เซลล์ ชีวมวล หรือขยะ เป็นการลงทุนระยะยาวที่มั่นคง แต่มีความซับซ้อนสูงเรื่องสัญญาและการยอมรับของชุมชน','การลงทุนในโรงไฟฟ้า (ไม่ว่าจะเป็นโซลาร์เซลล์ ชีวมวล หรือขยะ) เป็นการลงทุนระยะยาวที่มั่นคง แต่มีความซับซ้อนสูง','[{"label":"สัญญาซื้อขายไฟ (PPA)","detail":"ต้องดูว่ามีสัญญากับ กฟผ. หรือ กฟภ. ระยะเวลากี่ปี และราคาค่าไฟที่ได้คุ้มค่าไหม"},{"label":"การยอมรับของชุมชน","detail":"ต้องทำความเข้าใจและดูแลคนในพื้นที่ไม่ให้เกิดผลกระทบด้านสิ่งแวดล้อม"},{"label":"เทคโนโลยีและการบำรุงรักษา","detail":"เครื่องจักรและอุปกรณ์ต้องมีประสิทธิภาพสูงเพื่อไม่ให้สูญเสียพลังงานระหว่างผลิต"}]'),
(17,'shopping-bag','พื้นที่ขายสินค้า','ล็อกขายของ หรือ Community Mall ทำเลแบบไหนที่พ่อค้าแม่ค้าแย่งกันจอง?','ไม่ว่าจะเป็นตลาดนัด ตึกแถว หรือมอลล์เล็กๆ การทำพื้นที่ปล่อยเช่าให้ปัง ต้องมีแม่เหล็กดึงดูดคน จัดโซนนิ่งที่ดี และค่าเช่าที่สมเหตุสมผล','ไม่ว่าจะเป็นตลาดนัด ตึกแถว หรือมอลล์เล็กๆ การจะทำพื้นที่ปล่อยเช่าให้ปัง ต้องดูสิ่งเหล่านี้','[{"label":"มีแม่เหล็กดึงดูดคน","detail":"เช่น มีซูเปอร์มาร์เก็ตเจ้าดัง หรือร้านอาหารฮิตๆ มาเปิดเพื่อดึงคนเข้าพื้นที่"},{"label":"การจัดโซนนิ่ง (Zoning)","detail":"ไม่ควรให้ร้านประเภทเดียวกันอยู่ติดกันเยอะเกินไป และต้องเดินง่าย ไม่สับสน"},{"label":"ค่าเช่าที่สมเหตุสมผล","detail":"ต้องตั้งราคาที่พ่อค้าแม่ค้าอยู่ได้ เราถึงจะอยู่ได้ในระยะยาว"}]'),
(18,'monitor','สื่อโฆษณานอกบ้าน','ป้ายบิลบอร์ดและจอ LED... อสังหาฯ แนวตั้งที่สร้างรายได้แบบ Passive Income','ที่ดินเปล่าหรือดาดฟ้าตึกบางแห่ง อาจจะสร้างรายได้มหาศาลจากการปล่อยเช่าทำป้ายโฆษณา แต่ต้องดูทัศนวิสัย โครงสร้าง และกฎหมายป้ายให้ชัดก่อน','ที่ดินเปล่าหรือดาดฟ้าตึกบางแห่ง อาจจะสร้างรายได้มหาศาลจากการปล่อยเช่าทำป้ายโฆษณา','[{"label":"ทัศนวิสัย (Visibility)","detail":"ป้ายต้องอยู่ในมุมที่มองเห็นชัดเจน ไม่มีต้นไม้หรือตึกอื่นมาบัง และอยู่ในจุดที่รถติดนานๆ ยิ่งดี"},{"label":"ความปลอดภัยของโครงสร้าง","detail":"ป้ายขนาดใหญ่ต้องได้รับใบอนุญาตก่อสร้างและมีการตรวจสอบความแข็งแรงเพื่อป้องกันอุบัติเหตุจากลมพายุ"},{"label":"กฎหมายและภาษีป้าย","detail":"ต้องเช็กเทศบัญญัติของพื้นที่นั้นๆ ว่าอนุญาตให้ติดป้ายขนาดเท่าไหร่ และมีค่าภาษีป้ายที่ต้องจ่ายต่อปีเท่าไหร่"}]'),
(19,'camera','สตูดิโอ','สร้าง "สตูดิโอ" ให้เช่าถ่ายงาน... อะไรคือสิ่งที่โปรดักชั่นมองหา?','สตูดิโอถ่ายภาพ ถ่ายโฆษณา หรือถ่ายรายการ เป็นอสังหาฯ เฉพาะกลุ่มที่เน้นความเป๊ะเรื่องฟังก์ชัน ทั้งการเก็บเสียง ความสูงเพดาน และที่จอดรถกองถ่าย','สตูดิโอถ่ายภาพ ถ่ายโฆษณา หรือถ่ายรายการ เป็นอสังหาฯ เฉพาะกลุ่มที่เน้นความเป๊ะเรื่องฟังก์ชัน','[{"label":"การเก็บเสียง (Soundproof)","detail":"สำคัญที่สุด! ถ้าเสียงรถ เสียงฝนตกทะลุเข้ามา งานโปรดักชั่นจะพังทันที"},{"label":"ความสูงของเพดาน","detail":"ต้องสูงพอที่จะเซ็ตไฟ แขวนโครงสร้าง หรือส่องไฟลงมาจากด้านบนได้สะดวก"},{"label":"ที่จอดรถสำหรับรถกองถ่าย","detail":"รถทีมงานมักจะคันใหญ่และมีหลายคัน ต้องมีพื้นที่จอดและขนย้ายอุปกรณ์เข้า-ออกได้ง่าย"}]'),
(20,'server','Data Center','Data Center... บ้านของข้อมูลยุคดิจิทัล ที่ต้องการความเสถียรขั้นสุด','Data Center เป็นอสังหาฯ ที่ฮอตมากในยุค AI และ Cloud แต่การหาที่ตั้งมีเงื่อนไขเข้มงวด ทั้งเรื่องระบบไฟ ระบบความเย็น และความปลอดภัยจากภัยธรรมชาติ','Data Center เป็นอสังหาฯ ที่ฮอตมากในยุค AI และ Cloud แต่การหาที่ตั้งมีเงื่อนไขที่เข้มงวดมาก','[{"label":"ความเสถียรของระบบไฟ","detail":"ต้องมีแหล่งจ่ายไฟสำรองขนาดใหญ่ และไม่มีประวัติไฟดับบ่อย"},{"label":"ระบบความเย็นที่ดีเยี่ยม","detail":"เซิร์ฟเวอร์ทำงานตลอดเวลาจนเกิดความร้อนสูง ระบบระบายความร้อนต้องทำงานได้ยี่สิบสี่ชั่วโมง"},{"label":"ปลอดภัยจากภัยธรรมชาติ","detail":"ทำเลต้องไม่อยู่ในพื้นที่เสี่ยงน้ำท่วม ดินไหว หรือดินถล่มเด็ดขาด"}]'),
(21,'music','สถานบันเทิง','ลงทุนทำ "สถานบันเทิง" คอนเนคชันและทำเลต้องมาคู่กัน','การทำผับ บาร์ หรือเลานจ์ เป็นธุรกิจที่สร้างกระแสเงินสดได้ดี แต่ต้องระวังเรื่องใบอนุญาต ระบบเก็บเสียง และที่จอดรถเป็นพิเศษ','การทำผับ บาร์ หรือเลานจ์ เป็นธุรกิจที่สร้างกระแสเงินสดได้ดี แต่มีเรื่องที่ต้องระวังเป็นพิเศษ','[{"label":"ใบอนุญาตสถานบริการ","detail":"เป็นสิ่งที่หายากและมีโควตาจำกัด การซื้อกิจการที่มีใบอนุญาตพร้อมอยู่แล้วจึงมีมูลค่าสูงมาก"},{"label":"ระบบการเก็บเสียงและทางหนีไฟ","detail":"ต้องได้มาตรฐานตามที่กฎหมายกำหนดเพื่อความปลอดภัยของลูกค้าและไม่กวนใจเพื่อนบ้าน"},{"label":"ที่จอดรถและการเดินทาง","detail":"ยิ่งใกล้รถไฟฟ้า หรือมีบริการ Valet Parking ยิ่งดึงดูดลูกค้ากระเป๋าหนัก"}]'),
(22,'smile','สวนสนุก / สวนน้ำ','สวนสนุกและสวนน้ำ... การเนรมิตที่ดินเปล่าให้เป็นดินแดนแห่งความสุข','การลงทุนในสวนสนุกหรือสวนน้ำใช้เงินทุนสูงมาก หัวใจสำคัญที่จะทำให้ธุรกิจรอดและรุ่งคือ Maintenance กิจกรรมที่หลากหลาย และการบริหารจัดการพื้นที่ร่ม','การลงทุนในสวนสนุกหรือสวนน้ำใช้เงินทุนสูงมาก หัวใจสำคัญที่จะทำให้ธุรกิจรอดและรุ่งคือ','[{"label":"การบำรุงรักษาเครื่องเล่น (Maintenance)","detail":"ความปลอดภัยต้องมาเป็นอันดับ 1 มีตารางตรวจเช็กเครื่องเล่นและระบบน้ำทุกวัน"},{"label":"กิจกรรมที่หลากหลาย","detail":"ต้องมีเครื่องเล่นสำหรับคนทุกวัย ตั้งแต่เด็กเล็กไปจนถึงวัยรุ่นสายลุย"},{"label":"การบริหารจัดการคิวและพื้นที่ร่ม","detail":"เมืองไทยอากาศร้อน การมีจุดนั่งพักในร่มและระบบจัดการคิวที่ดีจะช่วยให้ลูกค้าประทับใจ"}]'),
(23,'radio','โทรคมนาคม','อสังหาฯ เพื่อการสื่อสาร... เสาส่งสัญญาณและสถานีฐาน','การปล่อยเช่าพื้นที่ดาดฟ้าหรือที่ดินเพื่อตั้งเสาส่งสัญญาณ 5G หรือดาวเทียม เป็น Passive Income แบบหนึ่ง ที่ต้องดูสัญญา การเข้าถึง และความแข็งแรงของโครงสร้าง','การปล่อยเช่าพื้นที่ดาดฟ้าหรือที่ดินเพื่อตั้งเสาส่งสัญญาณ 5G หรือดาวเทียม เป็นเสือนอนกินอีกแบบหนึ่ง','[{"label":"สัญญาเช่าระยะยาว","detail":"ปกติค่ายมือถือมักจะทำสัญญาระยะยาว ทำให้เรามีรายได้มั่นคง"},{"label":"การเข้าถึงพื้นที่เพื่อซ่อมบำรุง","detail":"ต้องเปิดทางให้ช่างเทคนิคสามารถเข้ามาดูแลอุปกรณ์ได้ตลอด 24 ชั่วโมงในกรณีที่ระบบมีปัญหา"},{"label":"ความแข็งแรงของโครงสร้างตึก","detail":"หากตั้งบนดาดฟ้า วิศวกรต้องคำนวณแล้วว่าตึกรับน้ำหนักเสาและแรงลมได้สบายๆ"}]'),
(24,'anchor','กิจการเดินเรือ','ท่าเรือและกิจการเดินเรือ... อสังหาฯ ริมน้ำที่เชื่อมต่อการค้าโลก','ไม่ว่าจะเป็นท่าเรือขนส่งสินค้าหรือท่าเทียบเรือยอทช์ (Marina) ล้วนเป็นทรัพย์สินที่มีมูลค่ามหาศาล ต้องดูความลึกร่องน้ำ โครงสร้างหน้าท่า และพื้นที่ลานกองสินค้า','ไม่ว่าจะเป็นท่าเรือขนส่งสินค้า หรือท่าเทียบเรือยอทช์ (Marina) ล้วนเป็นทรัพย์สินที่มีมูลค่ามหาศาล','[{"label":"ความลึกของร่องน้ำ","detail":"ต้องลึกพอที่เรือขนาดใหญ่จะเข้ามาจอดเทียบท่าได้โดยไม่ติดสันดอน"},{"label":"โครงสร้างหน้าท่า (Quay)","detail":"ต้องแข็งแรง ทนทานต่อการกัดเซาะของน้ำเค็มและแรงกระแทกของเรือ"},{"label":"พื้นที่ลานกองสินค้าหรือโกดัง","detail":"สำหรับท่าเรือขนส่ง ต้องมีพื้นที่พักสินค้าที่บริหารจัดการได้อย่างรวดเร็ว"}]'),
(25,'navigation','สนามบิน','สนามบินส่วนบุคคล (Private Jet Terminal)... อสังหาฯ ระดับ Ultra Luxury','การเป็นเจ้าของหรือผู้บริหารลานจอดเครื่องบินส่วนบุคคล เป็นธุรกิจเฉพาะกลุ่มที่เติบโตขึ้นเรื่อยๆ ต้องผ่านมาตรฐานการบิน บริการระดับ 5 ดาว และโรงเก็บเครื่องบิน','การเป็นเจ้าของหรือผู้บริหารลานจอดเครื่องบินส่วนบุคคล หรือสนามบินเล็ก เป็นธุรกิจเฉพาะกลุ่มที่เติบโตขึ้นเรื่อยๆ','[{"label":"มาตรฐานความปลอดภัยทางการบิน","detail":"ต้องผ่านเกณฑ์การตรวจสอบที่เข้มงวดของสำนักงานการบินพลเรือน"},{"label":"การบริการระดับ 5 ดาว","detail":"ลูกค้ากลุ่มนี้ต้องการความรวดเร็ว เป็นส่วนตัว และการบริการที่เนี้ยบที่สุดตั้งแต่นาทีที่เครื่องแลนดิ้ง"},{"label":"โรงเก็บเครื่องบิน (Hangar)","detail":"ต้องมีขนาดใหญ่และระบบรักษาความปลอดภัยที่ดีเยี่ยมเพื่อดูแลเครื่องบินราคาแพงของลูกค้า"}]'),
(26,'git-merge','กิจการร่วมค้า (JV)','"Joint Venture" ทางลัดในการปั้นโครงการอสังหาฯ ยักษ์ใหญ่','บางครั้งโครงการมันใหญ่เกินกว่าจะทำคนเดียว การทำ Joint Venture หรือการร่วมทุนกันจึงเป็นทางออกที่ดี ต้องดูจุดเด่นแต่ละฝ่าย การแบ่งกำไร และการลดความเสี่ยง','บางครั้งโครงการมันใหญ่เกินกว่าจะทำคนเดียว การทำ Joint Venture หรือการร่วมทุนกันจึงเป็นทางออกที่ดี','[{"label":"การดึงจุดเด่นของแต่ละฝ่ายมาใช้","detail":"เช่น ฝ่ายหนึ่งมีที่ดินทำเลทอง อีกฝ่ายมีเงินทุนและแบรนด์ที่น่าเชื่อถือ พอมาเจอกันก็เกิดโครงการระดับ Masterpiece"},{"label":"การแบ่งสัดส่วนกำไรและหน้าที่ที่ชัดเจน","detail":"ต้องตกลงกันตั้งแต่แรกว่าใครจะดูแลส่วนไหน (ก่อสร้าง การตลาด หรือการบริหาร) เพื่อไม่ให้ทะเลาะกันทีหลัง"},{"label":"ลดความเสี่ยง","detail":"ช่วยกระจายความเสี่ยงในการลงทุน ไม่ต้องแบกรับภาระคนเดียวเต็มๆ"}]'),
(27,'edit-3','ออกแบบตกแต่งภายใน','เพราะบ้านที่ดี... ต้องเริ่มต้นจาก "ข้างใน"','การซื้ออสังหาฯ มาแล้ว สิ่งที่จะเปลี่ยนตึกเปล่าให้กลายเป็นบ้านหรือร้านค้าที่น่านั่งก็คือการออกแบบตกแต่งภายใน ต้องคำนึงถึงฟังก์ชัน วัสดุ และการสะท้อนตัวตน','การซื้ออสังหาฯ มาแล้ว สิ่งที่จะเปลี่ยนตึกเปล่าให้กลายเป็น "บ้าน" หรือ "ร้านค้าที่น่านั่ง" ก็คือการออกแบบตกแต่งภายใน','[{"label":"ฟังก์ชันต้องตอบโจทย์การใช้งานจริง","detail":"ไม่ใช่แค่สวยอย่างเดียว แต่ต้องเดินเหินสะดวก ปลั๊กไฟเพียงพอ และมีตู้เก็บของที่มิดชิด"},{"label":"การเลือกใช้วัสดุ","detail":"สวยและต้องทนทาน เหมาะกับไลฟ์สไตล์ (เช่น ถ้ามีสัตว์เลี้ยงก็ควรใช้วัสดุที่ทนรอยขีดข่วนได้ดี)"},{"label":"สะท้อนตัวตนของเจ้าของ","detail":"นักออกแบบที่ดีจะช่วยดึงสไตล์ที่คุณชอบ ออกมาเป็นผลงานที่มองแล้วไม่เบื่อ"}]');

SET FOREIGN_KEY_CHECKS = 1;

-- -------------------------------------------------------
-- Admin Activity Log
-- -------------------------------------------------------

CREATE TABLE IF NOT EXISTS `admin_activity_log` (
  `id`         INT AUTO_INCREMENT PRIMARY KEY,
  `admin_id`   INT NOT NULL,
  `admin_name` VARCHAR(100) NOT NULL,
  `action`     ENUM('create','update','delete') NOT NULL,
  `entity`     VARCHAR(50) NOT NULL,
  `entity_id`  INT DEFAULT NULL,
  `label`      VARCHAR(255) DEFAULT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_created_at` (`created_at`),
  INDEX `idx_admin_id`   (`admin_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

